style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
body {
    background: url("data:image/png;base64,") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #c9c9ff !important;
    font-family: 'Consolas', 'Courier New', monospace !important;
  }

  * {
    background-color: rgba(0, 0, 0, 0.4) !important;
    border-color: #2f2f4f !important;
  }

  a {
    color: #aaffee !important;
  }

  ::selection {
    background-color: #39ff14 !important;
    color: #000 !important;
  }

  input, textarea, select, button {
    background-color: rgba(10, 10, 20, 0.6) !important;
    color: #e0e0ff !important;
    border: 1px solid #3f3f5f !important;
  }
}
